80	/****************************************************************************
81	 * Private Functions - Register Access Helpers
82	 ****************************************************************************/
83	
84	static inline uint32_t getreg32(uintptr_t addr)
85	{
86	  return *(volatile uint32_t *)addr;
87	}
88	
89	static inline void putreg32(uint32_t val, uintptr_t addr)
90	{
91	  *(volatile uint32_t *)addr = val;
92	}
93	
94	static void reset_assert(unsigned int id)
95	{
96	  unsigned int bank = id / 32;
97	  unsigned int bit = id % 32;
98	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
99	
100	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
101	}
102	
103	static void reset_deassert(unsigned int id)
104	{
105	  unsigned int bank = id / 32;
106	  unsigned int bit = id % 32;
107	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
108	
109	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
110	}
111	
112	static void clk_reset_deassert(unsigned int id)
113	{
114	  unsigned int bank = id / 32;
115	  unsigned int bit = id % 32;
116	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
117	  uint32_t reg = getreg32(addr);
118	
119	  putreg32(reg | (1u << bit), addr);
120	}
