164	/****************************************************************************
165	 * Private Functions - DMA Software Reset
166	 ****************************************************************************/
167	
168	static int dma_soft_reset(uintptr_t gmac_base)
169	{
170	  uint32_t val;
171	  int timeout = 100000;
172	
173	  val = getreg32(gmac_base + DMA_BUS_MODE);
174	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
175	         "\n", val);
176	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
177	
178	  do
179	    {
180	      val = getreg32(gmac_base + DMA_BUS_MODE);
181	      if (!(val & DMA_SFT_RESET))
182	        {
183	          return 0;
184	        }
185	
186	      up_udelay(10);
187	    }
188	  while (--timeout > 0);
189	
190	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
191	         " hw_feature0=0x%08" PRIX32 "\n",
192	         getreg32(gmac_base + DMA_BUS_MODE),
193	         getreg32(gmac_base + DMA_HW_FEATURE));
194	  return -1;
195	}
