550	
551	static int phy_config_init(struct sg2000_eth_priv_s *priv)
552	{
553	  uint16_t bmsr;
554	  uint16_t bmcr;
555	  uint16_t anlpar;
556	  int timeout;
557	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
558	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
559	  uint32_t phy_id = (id1 << 16) | id2;
560	
561	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
562	         " expect=0x00435649\n", phy_id);
563	
564	  if (phy_id == 0xffffffff)
565	    {
566	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
567	      return -1;
568	    }
569	
570	  if (phy_id != CVITEK_PHY_ID)
571	    {
572	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
573	             "\n", phy_id);
574	    }
575	
576	  priv->speed = 100;
577	  priv->duplex = 1;
578	
579	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
580	  up_mdelay(10);
581	
582	  timeout = 100;
583	  do
584	    {
585	      bmcr = mdio_read(priv->gmac_base, 0, 0);
586	      if (!(bmcr & 0x8000))
587	        {
588	          break;
589	        }
590	
591	      up_mdelay(1);
592	    }
593	  while (--timeout > 0);
594	
595	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
596	
597	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
598	
599	  bmcr = mdio_read(priv->gmac_base, 0, 0);
600	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
601	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
602	         bmcr | 0x1200);
603	
604	  timeout = 50;
605	  do
606	    {
607	      (void)mdio_read(priv->gmac_base, 0, 1);
608	      bmsr = mdio_read(priv->gmac_base, 0, 1);
609	      if ((bmsr & 0x0004) != 0)
610	        {
611	          break;
612	        }
613	
614	      up_mdelay(100);
615	    }
616	  while (--timeout > 0);
617	
618	  if ((bmsr & 0x0004) == 0)
619	    {
620	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
621	             bmsr);
622	      priv->link_up = 0;
623	      return OK;
624	    }
625	
626	  anlpar = mdio_read(priv->gmac_base, 0, 5);
627	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
628	         "ANLPAR=0x%04X\n", bmsr, anlpar);
629	
630	  if ((anlpar & 0x0100) != 0)
631	    {
632	      priv->speed = 100;
633	      priv->duplex = 1;
634	    }
635	  else if ((anlpar & 0x0080) != 0)
636	    {
637	      priv->speed = 100;
638	      priv->duplex = 0;
639	    }
640	  else if ((anlpar & 0x0040) != 0)
641	    {
642	      priv->speed = 10;
643	      priv->duplex = 1;
644	    }
645	  else
646	    {
647	      priv->speed = 10;
648	      priv->duplex = 0;
649	    }
650	
651	  priv->link_up = 1;
652	
653	  return 0;
654	}
