656	/****************************************************************************
657	 * Private Functions - DMA Descriptor Management
658	 ****************************************************************************/
659	
660	static int alloc_dma(struct sg2000_eth_priv_s *priv)
661	{
662	  int i;
663	
664	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
665	                                sizeof(struct sg2000_dma_desc_s));
666	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
667	                                sizeof(struct sg2000_dma_desc_s));
668	
669	  if (!priv->tx_desc || !priv->rx_desc)
670	    {
671	      return -ENOMEM;
672	    }
673	
674	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
676	
677	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
678	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
679	   */
680	
681	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
682	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
683	
684	  for (i = 0; i < TX_RING_SIZE; i++)
685	    {
686	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
687	      if (!priv->tx_buf[i])
688	        {
689	          return -ENOMEM;
690	        }
691	
692	      priv->tx_pkt[i] = NULL;
693	    }
694	
695	  for (i = 0; i < RX_RING_SIZE; i++)
696	    {
697	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
698	      if (!priv->rx_buf[i])
699	        {
700	          return -ENOMEM;
701	        }
702	
703	      /* Touch and clean each RX buffer's cache lines now, so there
704	       * are no dirty cache lines from previous heap use that could
705	       * later be written back and overwrite DMA-received data.
706	       */
707	
708	      memset(priv->rx_buf[i], 0, RX_BUF_SIZE);
709	    }
710	
711	  /* Flush the zeroed RX buffers to DDR.  After this, RX buffers have
712	   * clean cache lines — safe for DMA to write into without risk of
713	   * stale dirty lines being written back later.
714	   */
715	
716	  c906_clean_dcache_range((uintptr_t)priv->rx_desc,
717	                          (uintptr_t)priv->rx_desc +
718	                          RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
719	
720	  for (i = 0; i < RX_RING_SIZE; i++)
721	    {
722	      c906_clean_dcache_range((uintptr_t)priv->rx_buf[i],
723	                              (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
724	    }
725	
726	  return 0;
727	}
728	
729	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
730	{
731	  uintptr_t base = priv->gmac_base;
732	  int i;
733	
734	  /* Initialize TX descriptors.
735	   * Mark the last descriptor with END_RING so DMA knows the ring boundary.
736	   */
737	
738	  for (i = 0; i < TX_RING_SIZE; i++)
739	    {
740	      /* Enhanced format: TER in des0[21], des1 = buffer size only */
741	      priv->tx_desc[i].des0 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
742	      priv->tx_desc[i].des1 = 0;
743	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
744	      priv->tx_desc[i].des3 = 0;
745	      priv->tx_pkt[i] = NULL;
746	    }
747	
748	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
749	   * Mark the last descriptor with RER (RX End of Ring) in des1.
750	   */
751	
752	  for (i = 0; i < RX_RING_SIZE; i++)
753	    {
754	      priv->rx_desc[i].des0 = DESC_OWN;
755	      priv->rx_desc[i].des1 = RX_BUF_SIZE |
756	                              ((i == RX_RING_SIZE - 1) ? RX_DESC_RER : 0);
757	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
758	      priv->rx_desc[i].des3 = 0;
759	    }
760	
761	  priv->tx_cur = 0;
762	  priv->tx_dirty = 0;
763	  priv->tx_free_idx = 0;
764	  priv->tx_complete_count = 0;
765	  priv->rx_pending = false;
766	  priv->rx_cur = 0;
767	
768	  /* Flush all descriptor writes from D-cache to DDR.
769	   * Without this, DMA will read stale (zeroed) descriptor data
770	   * and immediately set TU / RU in CSR5.
771	   * Use address-range clean — only touches descriptor memory.
772	   */
773	
774	  c906_clean_dcache_range((uintptr_t)priv->tx_desc,
775	                          (uintptr_t)priv->tx_desc +
776	                          TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
777	  c906_clean_dcache_range((uintptr_t)priv->rx_desc,
778	                          (uintptr_t)priv->rx_desc +
779	                          RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
780	  C906_SYNC_S();
781	
782	  /* Verify descriptor size compatibility before configuring DMA Bus Mode.
783	   *
784	   * ATDS=0 uses normal 16-byte descriptors (OWN in TDES0, control bits
785	   * FS/LS/IC/TER in TDES1).  The descriptor size is always 16 bytes
786	   * regardless of the timestamp engine state, so the 32-byte extended
787	   * descriptor problem does not apply here.
788	   *
789	   * We still log HW_FEATURE for diagnostics and explicitly disable the
790	   * timestamp engine if present (timestamp is not used by this driver).
791	   */
792	  {
793	    uint32_t hw_feat = getreg32(base + DMA_HW_FEATURE);
794	
795	    syslog(LOG_INFO,
796	           "sg2000_eth: DMA_HW_FEATURE=0x%08" PRIX32 "\n", hw_feat);
797	
798	    if (hw_feat & DMA_HW_FEATURE_TSEN)
799	      {
800	        /* Timestamp engine is present — not needed, keep it off. */
801	
802	        uint32_t ts_ctrl = getreg32(base + GMAC_TIMESTAMP_CTRL);
803	
804	        if (ts_ctrl & GMAC_TS_TSENA)
805	          {
806	            putreg32(ts_ctrl & ~GMAC_TS_TSENA,
807	                     base + GMAC_TIMESTAMP_CTRL);
808	            syslog(LOG_WARNING,
809	                   "sg2000_eth: timestamp was enabled; "
810	                   "disabled (not used)\n");
811	          }
812	
813	        syslog(LOG_INFO,
814	               "sg2000_eth: timestamp HW present, TSENA=0, "
815	               "ATDS=0 (16-byte normal desc)\n");
816	      }
817	    else
818	      {
819	        syslog(LOG_INFO,
820	               "sg2000_eth: no timestamp HW, "
821	               "ATDS=0 (16-byte normal desc)\n");
822	      }
823	  }
824	
825	  /* Configure DMA Bus Mode (CSR0): Fixed Burst, AAL, USP, PBL=8 (ATDS=0) */
826	  putreg32(DMA_BUS_DEFAULT, base + DMA_BUS_MODE);
827	
828	  /* Configure AXI Bus Mode (CSR10): burst lengths + OSR limits */
829	  putreg32(DMA_AXI_DEFAULT, base + DMA_AXI_BUS_MODE);
830	
831	  /* Write descriptor ring base addresses */
832	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
833	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
834	
835	  /* Mask all DMA interrupts via CSR7 (they are unmasked in start_mac_and_dma) */
836	  putreg32(0, base + DMA_INTR_ENA);
837	}
