839	/****************************************************************************
840	 * Private Functions - MAC and DMA Control
841	 ****************************************************************************/
842	
843	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
844	{
845	  uint32_t hi;
846	  uint32_t lo;
847	
848	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
849	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
850	
851	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
852	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
853	}
854	
855	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
856	{
857	  uintptr_t gmac_base = priv->gmac_base;
858	  uint32_t v;
859	
860	  /* Configure MAC based on PHY negotiation results */
861	
862	  v = GMAC_CORE_INIT;
863	  if (priv->speed == 100)
864	    {
865	      v |= GMAC_CONFIG_FES;   /* 100M */
866	    }
867	
868	  if (priv->duplex)
869	    {
870	      v |= GMAC_CONFIG_DM;    /* Full duplex */
871	    }
872	
873	  /* Enable MAC TX and RX */
874	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
875	
876	  putreg32(v, gmac_base + GMAC_CONFIG);
877	
878	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
879	   * Pass multicast + broadcast + unicast (promiscuous mode).
880	   */
881	
882	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
883	           gmac_base + GMAC_FRAME_FILTER);
884	
885	  /* Enable MAC interrupts */
886	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
887	
888	  /* Enable DMA interrupts via CSR7 */
889	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
890	
891	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
892	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
893	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
894	   */
895	
896	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
897	           DMA_CONTROL_ST | DMA_CONTROL_SR,
898	           gmac_base + DMA_CONTROL);
899	}
