901	/****************************************************************************
902	 * Private Functions - Doorbell Helpers
903	 ****************************************************************************/
904	
905	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
906	{
907	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
908	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
909	   */
910	
911	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
912	}
913	
914	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
915	{
916	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
917	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
918	   */
919	
920	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
921	}
