923	/****************************************************************************
924	 * Private Functions - Hardware Transmit
925	 ****************************************************************************/
926	
927	/* Forward declaration: processes deferred work from ISR in thread context.
928	 * Called from hw_transmit() and netdriver_receive().
929	 */
930	
931	static void process_deferred_work(struct sg2000_eth_priv_s *priv);
932	
933	static int hw_transmit(struct sg2000_eth_priv_s *priv,
934	                       const uint8_t *data, int len)
935	{
936	  unsigned int idx = priv->tx_cur;
937	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
938	  uint32_t csr5_before;
939	  uint32_t csr6;
940	
941	  /* Free any TX packets that were completed by DMA and counted by
942	   * tx_cleanup (ISR) since the last time we were here.  This must
943	   * happen in thread context — not in the ISR.
944	   */
945	
946	  process_deferred_work(priv);
947	
948	  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */
949	
950	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
951	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
952	
953	  /* Copy data to DMA TX buffer */
954	
955	  memcpy(priv->tx_buf[idx], data, len);
956	
957	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
958	
959	  /* Enhanced format: OWN | FS | LS | IC | TER all in des0.
960	   * des1 carries only the buffer size.
961	   * Preserve TER (END_RING) for the last descriptor.
962	   */
963	
964	  desc->des1 = (uint32_t)len;
965	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
966	               (desc->des0 & TX_DESC_TER);
967	
968	  /* Diagnostic: dump first 50 bytes of TX buffer (pointed to by des2) */
969	
970	  {
971	    int i;
972	    int dump_len = len < 50 ? len : 50;
973	
974	    syslog(LOG_INFO,
975	           "sg2000_eth: TX data[%u] des2=0x%08" PRIX32
976	           " first %d bytes:",
977	           idx, desc->des2, dump_len);
978	
979	    for (i = 0; i < dump_len; i += 16)
980	      {
981	        int row = 0;
982	        char hex[64];
983	        char ascii[20];
984	        int j;
985	
986	        row += snprintf(hex + row, sizeof(hex) - row, "  %04x:", i);
987	
988	        for (j = 0; j < 16; j++)
989	          {
990	            if (i + j < dump_len)
991	              {
992	                row += snprintf(hex + row, sizeof(hex) - row,
993	                                " %02x", priv->tx_buf[idx][i + j]);
994	                ascii[j] = (priv->tx_buf[idx][i + j] >= 32 &&
995	                           priv->tx_buf[idx][i + j] < 127)
996	                           ? priv->tx_buf[idx][i + j] : '.';
997	              }
998	            else
999	              {
1000	                row += snprintf(hex + row, sizeof(hex) - row, "   ");
1001	                ascii[j] = ' ';
1002	              }
1003	          }
1004	
1005	        ascii[16] = '\0';
1006	        syslog(LOG_INFO, "%s  |%s|\n", hex, ascii);
1007	      }
1008	  }
1009	
1010	  /* Diagnostic: dump TX descriptor and DMA state before doorbell */
1011	
1012	  syslog(LOG_INFO,
1013	         "sg2000_eth: TX idx=%u len=%d\n"
1014	         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
1015	         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
1016	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1017	         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
1018	         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
1019	         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
1020	         idx, len,
1021	         desc->des0, desc->des1, desc->des2, desc->des3,
1022	         csr5_before, csr6,
1023	         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
1024	         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
1025	         data[0], data[1], data[2], data[3], data[4], data[5],
1026	         data[6], data[7], data[8], data[9], data[10], data[11],
1027	         data[12], data[13]);
1028	
1029	  /* Advance tx_cur so tx_cleanup (called from ISR on TX completion)
1030	   * can find this packet.  Packet is tracked in tx_pkt[idx] by the
1031	   * caller BEFORE this function is called, so the ISR can safely
1032	   * free it even if TX completes immediately.
1033	   */
1034	
1035	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1036	
1037	  /* Flush D-cache to DDR so DMA can see the descriptor and buffer.
1038	   * Only clean the specific cache lines we touched (buffer + descriptor),
1039	   * NOT the entire D-cache.  This avoids disturbing other kernel state.
1040	   */
1041	
1042	  c906_dma_flush_before_tx((uintptr_t)priv->tx_buf[idx], len,
1043	                           (uintptr_t)desc,
1044	                           sizeof(struct sg2000_dma_desc_s));
1045	
1046	  /* Ring the TX doorbell and return immediately.  TX completion is
1047	   * handled by the ISR (DMA_STATUS_TI → tx_cleanup → netpkt_free →
1048	   * netdev_lower_txdone).  No polling needed.
1049	   */
1050	
1051	  tx_doorbell(priv);
1052	
1053	  return 0;
1054	}
1055	
1056	/****************************************************************************
1057	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1058	 ****************************************************************************/
1059	
1060	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1061	{
1062	  /* Called from ISR context.  Only advance tx_dirty and increment the
1063	   * completion counter — do NOT free netpkts or call netdev_lower_txdone.
1064	   * Those heap operations must happen in thread context (process_tx_deferred)
1065	   * to avoid corrupting the heap when an ISR interrupts an ongoing malloc/free.
1066	   */
1067	
1068	  while (priv->tx_dirty != priv->tx_cur)
1069	    {
1070	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1071	
1072	      /* Invalidate only this descriptor's cache line to see
1073	       * DMA's write-back (OWN cleared).  Targeted invalidate
1074	       * is safe in ISR context — it does NOT write back other
1075	       * dirty cache lines that may belong to heap metadata
1076	       * being modified by a preempted thread.
1077	       */
1078	
1079	      C906_SYNC_S();
1080	      c906_invalidate_dcache_range((uintptr_t)desc,
1081	                                    (uintptr_t)desc +
1082	                                    sizeof(struct sg2000_dma_desc_s));
1083	
1084	      if (desc->des0 & DESC_OWN)
1085	        {
1086	          break;
1087	        }
1088	
1089	      /* DMA completed this slot — count it but defer the free.
1090	       * The tx_pkt[] pointer is still valid; process_tx_deferred()
1091	       * will free it from thread context.
1092	       */
1093	
1094	      priv->tx_complete_count++;
1095	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1096	    }
1097	}
1098	
1099	/****************************************************************************
1100	 * Name: process_deferred_work
1101	 *
1102	 * Description:
1103	 *   Process work items that were deferred from ISR context:
1104	 *   1. Free completed TX packets (tx_cleanup advanced tx_dirty; we free).
1105	 *   2. Signal RX ready (ISR set rx_pending; we call netdev_lower_rxready).
1106	 *
1107	 *   Must ONLY be called from thread context — never from ISR.
1108	 *
1109	 ****************************************************************************/
1110	
1111	static void process_deferred_work(struct sg2000_eth_priv_s *priv)
1112	{
1113	  /* 1. Free completed TX packets that tx_cleanup (ISR) marked as done. */
1114	
1115	  while (priv->tx_free_idx != priv->tx_dirty)
1116	    {
1117	      if (priv->tx_pkt[priv->tx_free_idx] != NULL)
1118	        {
1119	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_free_idx],
1120	                      NETPKT_TX);
1121	          priv->tx_pkt[priv->tx_free_idx] = NULL;
1122	          netdev_lower_txdone(&priv->dev);
1123	        }
1124	
1125	      priv->tx_free_idx = (priv->tx_free_idx + 1) &
1126	                          (TX_RING_SIZE - 1);
1127	    }
1128	
1129	  /* 2. If the ISR flagged an RX frame arrival, notify the upper half.
1130	   *    netdev_lower_rxready may allocate netpkts internally, so it must
1131	   *    run in thread context, not ISR context.
1132	   */
1133	
1134	  if (priv->rx_pending)
1135	    {
1136	      priv->rx_pending = false;
1137	      netdev_lower_rxready(&priv->dev);
1138	    }
1139	}
1140	
1141	/****************************************************************************
1142	 * Private Functions - ISR
1143	 ****************************************************************************/
1144	
1145	static int sg2000_eth_isr(int irq, void *context, void *arg)
1146	{
1147	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1148	  uintptr_t base = priv->gmac_base;
1149	  uint32_t status;
1150	  uint32_t mac;
1151	
1152	  /* Clear MAC interrupts */
1153	
1154	  mac = getreg32(base + GMAC_INT_STATUS);
1155	  if (mac)
1156	    {
1157	      putreg32(mac, base + GMAC_INT_STATUS);
1158	    }
1159	
1160	  /* Read DMA Status (CSR5 at 0x1014) */
1161	
1162	  status = getreg32(base + DMA_STATUS);
1163	
1164	  if (!status)
1165	    {
1166	      return OK;
1167	    }
1168	
1169	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
1170	
1171	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1172	
1173	  if (status & DMA_STATUS_NIS)
1174	    {
1175	      /* Normal interrupt.
1176	       * IMPORTANT: do NOT call syslog or any heap-allocating function
1177	       * from ISR context — the network thread may be mid-malloc when
1178	       * we preempt it, corrupting the heap.
1179	       */
1180	
1181	      if (status & DMA_STATUS_RI)
1182	        {
1183	          /* Defer RX notification to thread context.
1184	           * Just set a flag; process_deferred_work() will call
1185	           * netdev_lower_rxready() from safe thread context.
1186	           */
1187	
1188	          priv->rx_pending = true;
1189	        }
1190	
1191	      if (status & DMA_STATUS_TI)
1192	        {
1193	          /* TX complete: only advances tx_dirty + counts.
1194	           * Actual netpkt_free happens later in thread context
1195	           * via process_deferred_work().
1196	           */
1197	
1198	          tx_cleanup(priv);
1199	        }
1200	    }
1201	
1202	  if (status & DMA_STATUS_AIS)
1203	    {
1204	      /* Abnormal interrupt — no logging in ISR context.
1205	       * The upper half will detect problems via link status
1206	       * or TX/RX timeouts.
1207	       */
1208	    }
1209	
1210	  return OK;
1211	}
1212	
1213	/****************************************************************************
1214	 * Name: sg2000_eth_tx_test
1215	 *
1216	 * Description:
1217	 *   Minimal hardware TX verification test.
1218	 *   Bypasses the network stack — directly programs a TX descriptor,
1219	 *   rings the doorbell, and verifies the DMA engine can:
1220	 *     Layer 1: Fetch the descriptor from DDR  (OWN bit cleared)
1221	 *     Layer 2: Read buffer data correctly     (no Underflow)
1222	 *     Layer 3: Generate TX Complete interrupt  (CSR5 TI bit)
1223	 *
1224	 *   Prerequisite: ifup has completed (PHY up, DMA running).
1225	 *
1226	 ****************************************************************************/
1227	
1228	static int sg2000_eth_tx_test(void)
1229	{
1230	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1231	  unsigned int idx = priv->tx_cur;
1232	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1233	  uint32_t csr5_before;
1234	  uint32_t csr5_after;
1235	  uint32_t csr6;
1236	  int timeout;
1237	  int test_len = 64;
1238	  int ret = 0;
1239	
1240	  /* STEP 0: Pre-flight checks */
1241	
1242	  if (!priv->link_up)
1243	    {
1244	      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
1245	      return -ENETDOWN;
1246	    }
1247	
1248	  if (desc->des0 & DESC_OWN)
1249	    {
1250	      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
1251	      return -EBUSY;
1252	    }
1253	
1254	  syslog(LOG_INFO,
1255	         "=== sg2000_eth TX hardware test ===\n"
1256	         "  tx_desc[%u]=%p  tx_buf=%p  test_len=%d\n"
1257	         "  NuttX IRQ=%d  GMAC_BASE=0x%08" PRIX32 "\n",
1258	         idx, desc, priv->tx_buf[idx], test_len,
1259	         priv->irq, (uint32_t)priv->gmac_base);
1260	
1261	  /* STEP 1: Build a minimal broadcast ARP frame.
1262	   * dst=ff:ff:ff:ff:ff:ff  src=our MAC  type=0x0806  payload=0xAA
1263	   */
1264	
1265	  memset(priv->tx_buf[idx], 0, test_len);
1266	  memset(priv->tx_buf[idx], 0xff, 6);
1267	  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);
1268	  priv->tx_buf[idx][12] = 0x08;
1269	  priv->tx_buf[idx][13] = 0x06;
1270	  memset(priv->tx_buf[idx] + 14, 0xaa, test_len - 14);
1271	
1272	  /* STEP 2: Snapshot hardware state before submission.
1273	   * Invalidate descriptor cache line first so des0/des2
1274	   * diagnostics reflect the true DDR values, not stale cache.
1275	   */
1276	
1277	  C906_SYNC_S();
1278	  c906_invalidate_dcache_range((uintptr_t)desc,
1279	                                (uintptr_t)desc +
1280	                                sizeof(struct sg2000_dma_desc_s));
1281	
1282	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
1283	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1284	  {
1285	    uint32_t csr7 = getreg32(priv->gmac_base + DMA_INTR_ENA);
1286	
1287	    syslog(LOG_INFO,
1288	           "tx_test: BEFORE doorbell\n"
1289	           "  desc des0=0x%08" PRIX32 " des2=0x%08" PRIX32 "\n"
1290	           "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1291	           " CSR7=0x%08" PRIX32 " TX_FSM=%u\n",
1292	           desc->des0, desc->des2, csr5_before, csr6,
1293	           csr7, (csr5_before >> 20) & 0x7);
1294	  }
1295	
1296	  /* Clear stale TI / TU / ETI from CSR5 so the test starts clean.
1297	   * These bits may have been set during DMA init (TU fires when DMA
1298	   * finds all TX descriptors with OWN=0).  Without clearing, the
1299	   * polling loop would see a stale TI and report false success.
1300	   */
1301	
1302	  {
1303	    uint32_t csr5_clear = DMA_STATUS_TI | DMA_STATUS_TU |
1304	                          DMA_STATUS_UNF | DMA_STATUS_TPS |
1305	                          DMA_STATUS_TJT;
1306	    putreg32(csr5_clear, priv->gmac_base + DMA_STATUS);
1307	  }
1308	
1309	  /* Flush the CSR5 write to device before proceeding.
1310	   * DMA_STATUS is a device register — need fence to ensure the
1311	   * clear is visible before the descriptor OWN=1 is visible.
1312	   */
1313	
1314	  __asm__ volatile ("fence w,o" ::: "memory");
1315	
1316	  /* STEP 3: Program TX descriptor (Enhanced format).
1317	   *   des2 = buffer physical address
1318	   *   des1 = buffer size only
1319	   *   des0 = OWN | FS | LS | IC | TER
1320	   */
1321	
1322	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1323	  desc->des1 = (uint32_t)test_len;
1324	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
1325	               (desc->des0 & TX_DESC_TER);
1326	
1327	  /* STEP 4: Advance tx_cur BEFORE ringing the doorbell, mirroring
1328	   * hw_transmit.  This lets tx_cleanup (ISR) process this slot and
1329	   * increment tx_complete_count when DMA finishes.
1330	   */
1331	
1332	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1333	  priv->tx_pkt[idx] = NULL;
1334	
1335	  /* Snapshot the completion counter so we can verify the ISR ran */
1336	
1337	  {
1338	    int complete_snapshot = priv->tx_complete_count;
1339	
1340	    /* Flush only the buffer + descriptor cache lines */
1341	
1342	    c906_dma_flush_before_tx((uintptr_t)priv->tx_buf[idx], test_len,
1343	                             (uintptr_t)desc,
1344	                             sizeof(struct sg2000_dma_desc_s));
1345	
1346	    syslog(LOG_INFO, "tx_test: D-cache flushed (range), "
1347	           "ringing TX doorbell...\n");
1348	
1349	    /* STEP 5: Ring TX doorbell */
1350	
1351	    tx_doorbell(priv);
1352	
1353	    /* STEP 6: Poll OWN only.  Do NOT poll CSR5 TI — the ISR races
1354	     * with us and clears TI before we can read it.
1355	     */
1356	
1357	    timeout = 50000;
1358	    csr5_after = 0;
1359	
1360	    while (--timeout > 0)
1361	      {
1362	        /* Invalidate only this descriptor's cache line to see
1363	         * DMA's write-back, instead of hammering the entire
1364	         * D-cache with CIALL every 10 us.
1365	         */
1366	
1367	        C906_SYNC_S();
1368	        c906_invalidate_dcache_range((uintptr_t)desc,
1369	                                      (uintptr_t)desc +
1370	                                      sizeof(struct sg2000_dma_desc_s));
1371	
1372	        csr5_after = getreg32(priv->gmac_base + DMA_STATUS);
1373	
1374	        if (!(desc->des0 & DESC_OWN))
1375	          {
1376	            break;
1377	          }
1378	
1379	        up_udelay(10);
1380	      }
1381	
1382	    /* STEP 7: Wait a bit for the ISR to run and increment the
1383	     * completion counter, then verify layer by layer.
1384	     */
1385	
1386	    if (timeout > 0)
1387	      {
1388	        int isr_wait;
1389	
1390	        for (isr_wait = 0; isr_wait < 10000; isr_wait++)
1391	          {
1392	            if (priv->tx_complete_count != complete_snapshot)
1393	              {
1394	                break;
1395	              }
1396	
1397	            up_udelay(10);
1398	          }
1399	      }
1400	
1401	    syslog(LOG_INFO,
1402	           "tx_test: waited %d us  timeout=%s\n"
1403	           "  CSR5=0x%08" PRIX32 " TI=%s  tx_complete=%d (was %d)\n",
1404	           (50000 - timeout) * 10,
1405	           timeout > 0 ? "no" : "YES",
1406	           csr5_after,
1407	           (csr5_after & DMA_STATUS_TI) ? "SET" : "clear",
1408	           priv->tx_complete_count, complete_snapshot);
1409	
1410	    /* Layer 1: Did DMA clear OWN? */
1411	
1412	    if (desc->des0 & DESC_OWN)
1413	      {
1414	        syslog(LOG_ERR,
1415	               "*** FAIL [L1]: OWN still set — DMA did NOT fetch "
1416	               "descriptor!\n"
1417	               "  CSR5=0x%08" PRIX32 " TX_FSM=%u\n",
1418	               csr5_after, (csr5_after >> 20) & 0x7);
1419	        ret = -ETIMEDOUT;
1420	        goto out;
1421	      }
1422	
1423	    syslog(LOG_INFO,
1424	           "  [L1 PASS] DMA fetched descriptor (OWN cleared)\n");
1425	
1426	    /* Layer 2: Underflow / error check */
1427	
1428	    if (csr5_after & DMA_STATUS_UNF)
1429	      {
1430	        syslog(LOG_ERR,
1431	               "*** FAIL [L2]: TX Underflow — DMA could not read "
1432	               "buffer data!\n  CSR5=0x%08" PRIX32 "\n",
1433	               csr5_after);
1434	        ret = -EIO;
1435	        goto out;
1436	      }
1437	
1438	    if (desc->des0 & TX_DESC_ES)
1439	      {
1440	        syslog(LOG_ERR,
1441	               "*** FAIL [L2]: TX Error Summary in des0=0x%08"
1442	               PRIX32 "\n", desc->des0);
1443	        ret = -EIO;
1444	        goto out;
1445	      }
1446	
1447	    syslog(LOG_INFO,
1448	           "  [L2 PASS] No Underflow/Error — data read OK\n");
1449	
1450	    /* Layer 3: Did the TX complete ISR fire?
1451	     * We check tx_complete_count instead of CSR5 TI because the
1452	     * ISR clears TI (W1C) before we can poll it.
1453	     */
1454	
1455	    if (priv->tx_complete_count == complete_snapshot)
1456	      {
1457	        uint32_t csr7_now = getreg32(priv->gmac_base + DMA_INTR_ENA);
1458	        uint32_t csr5_now = getreg32(priv->gmac_base + DMA_STATUS);
1459	        uint32_t gmac_isr = getreg32(priv->gmac_base + GMAC_INT_STATUS);
1460	
1461	        syslog(LOG_ERR,
1462	               "*** FAIL [L3]: ISR did NOT process TX completion "
1463	               "(tx_complete_count unchanged at %d)\n"
1464	               "  NuttX IRQ=%d  CSR5=0x%08" PRIX32
1465	               " CSR7=0x%08" PRIX32
1466	               " GMAC_INT_STATUS=0x%08" PRIX32 "\n"
1467	               "  CSR7 bits: TIE=%d RIE=%d NIE=%d AIE=%d\n"
1468	               "  CSR5 bits: TI=%d RI=%d NIS=%d AIS=%d\n",
1469	               complete_snapshot,
1470	               priv->irq, csr5_now, csr7_now, gmac_isr,
1471	               (csr7_now & 1) ? 1 : 0,          // TIE
1472	               (csr7_now >> 6) & 1,              // RIE
1473	               (csr7_now >> 16) & 1,             // NIE
1474	               (csr7_now >> 15) & 1,             // AIE
1475	               (csr5_now & 1) ? 1 : 0,           // TI
1476	               (csr5_now >> 6) & 1,              // RI
1477	               (csr5_now >> 16) & 1,             // NIS
1478	               (csr5_now >> 15) & 1);            // AIS
1479	        ret = -EIO;
1480	        goto out;
1481	      }
1482	
1483	    syslog(LOG_INFO,
1484	           "  [L3 PASS] ISR processed TX (tx_complete_count "
1485	           "%d → %d)\n",
1486	           complete_snapshot, priv->tx_complete_count);
1487	
1488	    syslog(LOG_INFO,
1489	           "=== TX TEST PASSED ===  total ~%d us\n",
1490	           (50000 - timeout) * 10);
1491	  }
1492	
1493	out:
1494	  /* tx_cur was already advanced before the doorbell (see STEP 4).
1495	   * Just clear any lingering interrupt bits so the test doesn't
1496	   * leave side effects for the normal TX path.
1497	   */
1498	
1499	  if (csr5_after & DMA_STATUS_TI)
1500	    {
1501	      putreg32(DMA_STATUS_TI, priv->gmac_base + DMA_STATUS);
1502	    }
1503	
1504	  return ret;
1505	}
1506	
1507	/****************************************************************************
1508	 * Name: netdriver_ifup
1509	 *
1510	 * Description:
1511	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1512	 *
1513	 ****************************************************************************/
1514	
1515	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1516	{
1517	  FAR struct sg2000_eth_priv_s *priv =
1518	      (FAR struct sg2000_eth_priv_s *)dev;
1519	  int ret;
1520	
1521	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1522	
1523	  /* Ensure GMAC clocks and resets are configured */
1524	
1525	  gmac_clock_enable();
1526	
1527	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1528	
1529	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1530	
1531	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1532	  up_mdelay(10);
1533	
1534	  ret = mdio_verify_phy(priv->gmac_base);
1535	  if (ret < 0)
1536	    {
1537	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1538	      return ret;
1539	    }
1540	
1541	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1542	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1543	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1544	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1545	
1546	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1547	
1548	  ret = phy_config_init(priv);
1549	  if (ret < 0)
1550	    {
1551	      nerr("ERROR: PHY init failed: %d\n", ret);
1552	      return ret;
1553	    }
1554	
1555	  ret = dma_soft_reset(priv->gmac_base);
1556	  if (ret < 0)
1557	    {
1558	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1559	             "diagnostics: %d\n", ret);
1560	      return ret;
1561	    }
1562	
1563	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1564	    {
1565	      ret = alloc_dma(priv);
1566	      if (ret < 0)
1567	        {
1568	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1569	          return ret;
1570	        }
1571	    }
1572	
1573	  init_desc_and_dma(priv);
1574	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1575	  start_mac_and_dma(priv);
1576	  rx_doorbell(priv);
1577	
1578	  /* Diagnostic: verify DMA state machines after initialization.
1579	   * TS[22:20]=TX state, RS[19:17]=RX state.  Both should show Running.
1580	   */
1581	
1582	  {
1583	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1584	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1585	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1586	    unsigned int rx_state = (csr5 >> 17) & 0x7;
1587	    static const char * const states[] = {
1588	      "Stopped", "Running(FetchDesc)", "Running(WaitEnd)",
1589	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1590	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1591	    };
1592	
1593	    syslog(LOG_INFO,
1594	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1595	           " CSR6=0x%08" PRIX32 "\n"
1596	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1597	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1598	           csr5, csr6,
1599	           tx_state, states[tx_state],
1600	           rx_state, states[rx_state],
1601	           priv->tx_desc[0].des0, priv->rx_desc[0].des0);
1602	  }
1603	
1604	  up_enable_irq(priv->irq);
1605	  netdev_lower_carrier_on(dev);
1606	
1607	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1608	         priv->speed, priv->duplex ? "Full" : "Half");
1609	
1610	  /* Run minimal HW TX verification before returning to upper half */
1611	
1612	  sg2000_eth_tx_test();
1613	
1614	  return OK;
1615	}
1616	
1617	/****************************************************************************
1618	 * Name: netdriver_ifdown
1619	 *
1620	 * Description:
1621	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1622	 *
1623	 ****************************************************************************/
1624	
1625	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1626	{
1627	  FAR struct sg2000_eth_priv_s *priv =
1628	      (FAR struct sg2000_eth_priv_s *)dev;
1629	  uint32_t v;
1630	
1631	  up_disable_irq(priv->irq);
1632	
1633	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1634	   * Clear ST (bit 13) and SR (bit 1).
1635	   */
1636	
1637	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1638	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1639	           priv->gmac_base + DMA_CONTROL);
1640	
1641	  /* Disable MAC TX/RX */
1642	
1643	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1644	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1645	           priv->gmac_base + GMAC_CONFIG);
1646	
1647	  netdev_lower_carrier_off(dev);
1648	
1649	  ninfo("netdriver_ifdown: interface down\n");
1650	
1651	  return OK;
1652	}
1653	
1654	/****************************************************************************
1655	 * Name: netdriver_transmit
1656	 *
1657	 * Description:
1658	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1659	 *   The driver takes ownership of the netpkt and MUST free it after TX
1660	 *   completion (or on error).
1661	 *
1662	 *   Returned Value:
1663	 *     OK on success (pkt queued for TX); negated errno on failure.
1664	 *
1665	 ****************************************************************************/
1666	
1667	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1668	                               FAR netpkt_t *pkt)
1669	{
1670	  FAR struct sg2000_eth_priv_s *priv =
1671	      (FAR struct sg2000_eth_priv_s *)dev;
1672	  unsigned int len = netpkt_getdatalen(dev, pkt);
1673	  uint8_t *tmp_buf = NULL;
1674	  const uint8_t *data;
1675	  int ret;
1676	
1677	  if (len > SG2000_ETH_BUFSIZE)
1678	    {
1679	      nerr("ERROR: TX packet too large: %u\n", len);
1680	      netpkt_free(dev, pkt, NETPKT_TX);
1681	      return -E2BIG;
1682	    }
1683	
1684	  /* Extract data from netpkt.  If fragmented, copy out to a heap buffer;
1685	   * otherwise use the IOB data pointer directly.
1686	   *
1687	   * A heap buffer is used instead of a stack buffer because
1688	   * SG2000_ETH_BUFSIZE (1600 bytes) risks stack overflow on the
1689	   * netdev thread which has a limited stack size.
1690	   */
1691	
1692	  if (netpkt_is_fragmented(pkt))
1693	    {
1694	      tmp_buf = kmm_malloc(SG2000_ETH_BUFSIZE);
1695	      if (!tmp_buf)
1696	        {
1697	          nerr("ERROR: kmm_malloc(%u) for TX copy buffer failed\n",
1698	               SG2000_ETH_BUFSIZE);
1699	          netpkt_free(dev, pkt, NETPKT_TX);
1700	          return -ENOMEM;
1701	        }
1702	
1703	      syslog(LOG_INFO,
1704	             "sg2000_eth: TX fragmented pkt, len=%u, "
1705	             "copied to heap buf=%p\n", len, tmp_buf);
1706	
1707	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1708	      data = tmp_buf;
1709	    }
1710	  else
1711	    {
1712	      data = netpkt_getdata(dev, pkt);
1713	      if (!data)
1714	        {
1715	          nerr("ERROR: netpkt_getdata returned NULL\n");
1716	          netpkt_free(dev, pkt, NETPKT_TX);
1717	          return -EINVAL;
1718	        }
1719	    }
1720	
1721	  /* Check if TX ring is full before proceeding */
1722	
1723	  {
1724	    unsigned int idx = priv->tx_cur;
1725	
1726	    if (priv->tx_desc[idx].des0 & DESC_OWN)
1727	      {
1728	        if (tmp_buf)
1729	          {
1730	            kmm_free(tmp_buf);
1731	          }
1732	
1733	        return -EBUSY;
1734	      }
1735	
1736	    /* Track this packet BEFORE calling hw_transmit.  TX completion
1737	     * is interrupt-driven — the ISR may fire immediately after the
1738	     * doorbell and must find the packet in tx_pkt[idx].
1739	     */
1740	
1741	    priv->tx_pkt[idx] = pkt;
1742	  }
1743	
1744	  /* Send via DMA (interrupt-driven, returns immediately) */
1745	
1746	  ret = hw_transmit(priv, data, len);
1747	
1748	  /* Free the temporary copy buffer if it was allocated.
1749	   * Safe to free here: hw_transmit() already memcpy'd data into the
1750	   * DMA TX buffer, which is independent of the source buffer.
1751	   */
1752	
1753	  if (tmp_buf)
1754	    {
1755	      kmm_free(tmp_buf);
1756	    }
1757	
1758	  if (ret < 0)
1759	    {
1760	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1761	
1762	      /* Clear the tracking slot on failure */
1763	      {
1764	        irqstate_t flags = up_irq_save();
1765	        unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1766	
1767	        priv->tx_pkt[slot] = NULL;
1768	        up_irq_restore(flags);
1769	      }
1770	
1771	      netpkt_free(dev, pkt, NETPKT_TX);
1772	      return ret;
1773	    }
1774	
1775	  return OK;
1776	}
1777	
1778	/****************************************************************************
1779	 * Name: netdriver_receive
1780	 *
1781	 * Description:
1782	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1783	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1784	 *   NULL if no more packets are available.
1785	 *
1786	 *   Returned Value:
1787	 *     A netpkt_t * containing the received packet, or NULL.
1788	 *
1789	 ****************************************************************************/
1790	
1791	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1792	{
1793	  FAR struct sg2000_eth_priv_s *priv =
1794	      (FAR struct sg2000_eth_priv_s *)dev;
1795	  FAR netpkt_t *pkt = NULL;
1796	  struct sg2000_dma_desc_s *desc;
1797	  uint32_t status;
1798	  int frame_len;
1799	  int ret;
1800	
1801	  /* Free any TX packets completed since the last RX poll.
1802	   * Safe here because netdriver_receive runs in thread context.
1803	   */
1804	
1805	  process_deferred_work(priv);
1806	
1807	  /* Check if there is a completed RX descriptor.
1808	   * CIAL: write back any dirty cache lines, then invalidate all.
1809	   * This ensures we see DMA's write-back (OWN=0, frame length, etc.)
1810	   * rather than stale cached data.
1811	   */
1812	
1813	  desc = &priv->rx_desc[priv->rx_cur];
1814	
1815	  /* Invalidate RX descriptor cache line to see DMA's write-back.
1816	   * Targeted invalidate — does not disturb other cache lines.
1817	   * RX buffer is invalidated later when we have a valid frame.
1818	   */
1819	
1820	  C906_SYNC_S();
1821	  c906_invalidate_dcache_range((uintptr_t)desc,
1822	                                (uintptr_t)desc +
1823	                                sizeof(struct sg2000_dma_desc_s));
1824	
1825	  if (desc->des0 & DESC_OWN)
1826	    {
1827	      /* DMA still owns it — no packet ready.
1828	       * This can happen if rxready was signaled spuriously or for
1829	       * a previous packet already consumed.
1830	       */
1831	
1832	      syslog(LOG_INFO,
1833	             "sg2000_eth: RX OWN still set  rx_cur=%u des0=0x%08"
1834	             PRIX32 "\n", priv->rx_cur, desc->des0);
1835	
1836	      return NULL;
1837	    }
1838	
1839	  status = desc->des0;
1840	
1841	  syslog(LOG_INFO,
1842	         "sg2000_eth: RX frame  rx_cur=%u des0=0x%08" PRIX32
1843	         " FL=%u\n", priv->rx_cur, status,
1844	         ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK));
1845	
1846	  /* Check for errors */
1847	
1848	  if (status & RX_DESC_ES)
1849	    {
1850	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1851	      goto refill;
1852	    }
1853	
1854	  /* Get frame length.  GMAC_CONFIG_ACS is set, so the hardware
1855	   * already strips the FCS; the length from the descriptor is the
1856	   * actual frame length without CRC.
1857	   */
1858	
1859	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK);
1860	
1861	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1862	    {
1863	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1864	      goto refill;
1865	    }
1866	
1867	  /* Allocate a netpkt for the received data */
1868	
1869	  pkt = netpkt_alloc(dev, NETPKT_RX);
1870	  if (!pkt)
1871	    {
1872	      nerr("ERROR: netpkt_alloc failed\n");
1873	      goto refill;
1874	    }
1875	
1876	  /* Invalidate RX buffer cache lines so we read DMA-written data
1877	   * from DDR instead of stale cached values.
1878	   */
1879	
1880	  C906_SYNC_S();
1881	  c906_invalidate_dcache_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1882	                                (uintptr_t)priv->rx_buf[priv->rx_cur] +
1883	                                frame_len);
1884	
1885	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1886	  if (ret < 0)
1887	    {
1888	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1889	      netpkt_free(dev, pkt, NETPKT_RX);
1890	      pkt = NULL;
1891	      goto refill;
1892	    }
1893	
1894	  syslog(LOG_INFO,
1895	         "sg2000_eth: RX pkt OK  len=%d  first bytes: "
1896	         "%02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x\n",
1897	         frame_len,
1898	         priv->rx_buf[priv->rx_cur][0], priv->rx_buf[priv->rx_cur][1],
1899	         priv->rx_buf[priv->rx_cur][2], priv->rx_buf[priv->rx_cur][3],
1900	         priv->rx_buf[priv->rx_cur][4], priv->rx_buf[priv->rx_cur][5],
1901	         priv->rx_buf[priv->rx_cur][6], priv->rx_buf[priv->rx_cur][7],
1902	         priv->rx_buf[priv->rx_cur][8], priv->rx_buf[priv->rx_cur][9],
1903	         priv->rx_buf[priv->rx_cur][10], priv->rx_buf[priv->rx_cur][11]);
1904	
1905	refill:
1906	  /* Return the descriptor to DMA (set OWN=1).
1907	   * Preserve RER (RX End of Ring) bit in des1 if set during init.
1908	   * Clean only this descriptor's cache line — no need to flush
1909	   * the entire cache.
1910	   */
1911	
1912	  desc->des0 = DESC_OWN;
1913	  desc->des1 = RX_BUF_SIZE | (desc->des1 & RX_DESC_RER);
1914	
1915	  c906_clean_dcache_range((uintptr_t)desc,
1916	                          (uintptr_t)desc +
1917	                          sizeof(struct sg2000_dma_desc_s));
1918	  C906_SYNC_S();
1919	  C906_DMA_FENCE();
1920	
1921	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1922	  rx_doorbell(priv);
1923	
1924	  return pkt;
1925	}
1926	
1927	/****************************************************************************
1928	 * Private Data - Operations Structure
1929	 *
1930	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1931	 ****************************************************************************/
1932	
1933	static const struct netdev_ops_s g_ops =
1934	{
1935	  netdriver_ifup,     /* ifup */
1936	  netdriver_ifdown,   /* ifdown */
1937	  netdriver_transmit, /* transmit */
1938	  netdriver_receive   /* receive */
1939	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1940	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1941	   * filtering scenarios.
1942	   */
1943	};
