1949	/****************************************************************************
1950	 * Name: sg2000_eth_initialize
1951	 *
1952	 * Description:
1953	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1954	 *   network stack as a netdev_lowerhalf_s device.
1955	 *
1956	 *   Called from board_late_initialize() during system bringup.
1957	 *
1958	 ****************************************************************************/
1959	
1960	int sg2000_eth_initialize(void)
1961	{
1962	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1963	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1964	  int ret;
1965	
1966	  if (g_eth_initialized)
1967	    {
1968	      ninfo("SG2000 Ethernet driver already initialized\n");
1969	      return OK;
1970	    }
1971	
1972	  memset(priv, 0, sizeof(*priv));
1973	  priv->gmac_base = SG2000_GMAC_BASE;
1974	  priv->phy_base = SG2000_EPHY_BASE;
1975	  priv->phy_top = SG2000_EPHY_TOP;
1976	
1977	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1978	
1979	  priv->mac_addr[0] = 0x02;
1980	  priv->mac_addr[1] = 0x00;
1981	  priv->mac_addr[2] = 0x00;
1982	  priv->mac_addr[3] = 0x00;
1983	  priv->mac_addr[4] = 0x00;
1984	  priv->mac_addr[5] = 0x01;
1985	
1986	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1987	         IFHWADDRLEN);
1988	
1989	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1990	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1991	  dev->ops              = &g_ops;
1992	
1993	  priv->irq = SG2000_IRQ_GMAC;
1994	
1995	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1996	  if (ret < 0)
1997	    {
1998	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1999	      return ret;
2000	    }
2001	
2002	  netdev_lower_carrier_off(dev);
2003	  g_eth_initialized = true;
2004	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
2005	
2006	  gmac_clock_enable();
2007	
2008	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
2009	  if (ret < 0)
2010	    {
2011	      nerr("ERROR: irq_attach failed: %d\n", ret);
2012	      return OK;
2013	    }
2014	
2015	  up_enable_irq(priv->irq);
2016	  ninfo("IRQ %d enabled\n", priv->irq);
2017	
2018	  return OK;
2019	}
